// GENERATED by scripts/sync.js from src/prices.js — edit the original, then run `npm run sync`.
// AI prices in US$ per 1 million tokens, used to turn token counts into cost.
// Prices change: edit them in Settings (they are saved as the `ai_prices` setting and override
// these defaults). Models with no price still have their tokens recorded; their cost shows as unknown.
const DEFAULT_PRICES = {
  // OpenAI
  'gpt-5': { input: 1.25, cached: 0.125, output: 10 },
  'gpt-5-mini': { input: 0.25, cached: 0.025, output: 2 },
  'gpt-5-nano': { input: 0.05, cached: 0.005, output: 0.4 },
  'gpt-4.1': { input: 2, cached: 0.5, output: 8 },
  'gpt-4.1-mini': { input: 0.4, cached: 0.1, output: 1.6 },
  'gpt-4.1-nano': { input: 0.1, cached: 0.025, output: 0.4 },
  'gpt-4o': { input: 2.5, cached: 1.25, output: 10 },
  'gpt-4o-mini': { input: 0.15, cached: 0.075, output: 0.6 },
  o3: { input: 2, cached: 0.5, output: 8 },
  'o4-mini': { input: 1.1, cached: 0.275, output: 4.4 },
  // Google
  'gemini-2.5-pro': { input: 1.25, cached: 0.31, output: 10 },
  'gemini-2.5-flash': { input: 0.3, cached: 0.075, output: 2.5 },
  'gemini-2.5-flash-lite': { input: 0.1, cached: 0.025, output: 0.4 },
  // Anthropic
  'claude-opus-4-1': { input: 15, cached: 1.5, output: 75 },
  'claude-sonnet-4-5': { input: 3, cached: 0.3, output: 15 },
  'claude-haiku-4-5': { input: 1, cached: 0.1, output: 5 }
};

// Exact model id, or a dated snapshot of it ("gpt-5-2025-08-07" uses "gpt-5"). "gpt-5.5" does NOT
// fall back to "gpt-5": an unknown model gets no price rather than a wrong one.
function priceFor(model, overrides = {}) {
  const table = { ...DEFAULT_PRICES, ...overrides };
  const id = String(model || '').replace(/^models\//, '');
  if (table[id]) return table[id];
  const base = Object.keys(table).filter((k) => new RegExp(`^${k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}-\\d{4}`).test(id)).sort((a, b) => b.length - a.length)[0];
  return base ? table[base] : null;
}

// usage = { input, cached, output } where input excludes cached tokens
function costUsd(model, usage, overrides) {
  const p = priceFor(model, overrides);
  if (!p) return null;
  const n = (x) => Number(x) || 0;
  return (n(usage.input) * p.input + n(usage.cached) * (p.cached ?? p.input) + n(usage.output) * p.output) / 1e6;
}

module.exports = { DEFAULT_PRICES, priceFor, costUsd };
